// One 4 KB pack slot per batch_job_ix, 64B-aligned as the pack contracts
// require and bounded like the mask below; zero-initialized once per
// thread, and the packers write only the 4 live columns/rows of a slot,
// so the padding they rely on stays zero for the thread's lifetime.
// Geometries the AMX kernels do not serve get a 1-element placeholder.
constexpr size_t amx_qpack_elems =
    amx_shape_ok ? max_minibatch_size * amx_attn::Q_PACK_ELEMS_2048 : 1;
alignas(64) thread_local uint16_t amx_qpack[amx_qpack_elems] = {};
// Bitmap with one bit per batch_job_ix, meaning "this token's Q group
// is already packed into amx_qpack": word batch_job_ix / 64, bit
// batch_job_ix % 64. Sized for the largest legal minibatch
// (items.size() <= max_minibatch_size).
uint64_t amx_packed_mask[(max_minibatch_size + 63) / 64] = {};
if (amx_on) {
  TRON_ASSERT_LE(items.size(), max_minibatch_size);
  amx_attn::begin_region();
}

